import{_ as o,l as s,o as e,c as i,v as t,p as l,x as n,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"一致性哈希","description":"","frontmatter":{"title":"一致性哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/consistent-hashing.md","filePath":"cs/consistent-hashing.md","lastUpdated":1789023840000}'),c={name:"cs/consistent-hashing.md"};function m(_,a,u,f,g,T){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="一致性哈希" tabindex="-1">一致性哈希 <a class="header-anchor" href="#一致性哈希" aria-label="Permalink to &quot;一致性哈希&quot;">​</a></h1><div class="epigraph"><p>机器与键都映射到环上；键跟顺时针第一台机器。加一台只动邻近弧上的键，不是全表 $\\bmod n$。</p><footer>—— 据 Karger, Lehman, Leighton, Panigrahy, Levine and Lewin, Consistent Hashing and Random Trees, STOC 1997；Karger et al. 后续 Web 缓存文献整理</footer></div><p><a href="/cs/perfect-hashing">上一课</a> 钉死静态槽。<a href="/cs/universal-hashing">通用散列</a> 的 \\(m\\) 一变，\\(h(x)\\bmod m\\) 几乎所有键换家。缓存集群、分片要的是<strong>扰动最小</strong>。本课不造 FKS 二级表。缺口是一致性哈希：环 + 虚拟节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 台机器，\\(\\bmod n\\) 在 \\(n\\to n+1\\) 时期望几乎全部键迁移。一致性：键、节点都哈希到 \\([0,1)\\) 环（或 \\(2^{w}\\)），键归属顺时针下一节点。新节点只接管它到前驱之间的弧。期望每键迁移比例 \\(\\Theta(1/n)\\)。缺口不是完美无碰撞，而是<strong>映射随节点集平滑变化</strong>。</p><p><span class="marginnote">Karger et al., <em>STOC</em>, 1997。虚拟节点：每机多个环上位置，改善负载方差。Rendezvous / 跳跃哈希是亲戚，本课点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：对键哈希，在有序节点环上后继（树或跳表）。增删节点：插/删环上点，只迁移受影响键。虚拟节点数 \\(v\\) 权衡均匀与元数据。权重机可按权重复制虚点。</p>',8)),(e(),l(p,null,{default:n(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20KEY%5B%22h(key)%22%5D%20--%3E%20RING%5B%22%E7%8E%AF%22%5D%0A%20%20NODE%5B%22h(node%2C%20v)%22%5D%20--%3E%20RING%0A%20%20RING%20--%3E%20OWN%5B%22%E9%A1%BA%E6%97%B6%E9%92%88%E4%B8%8B%E4%B8%80%E8%8A%82%E7%82%B9%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Count-Min：一致性解决放置；草图解决近似计数。不要在本课写限价簿分片。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载：无虚点时单机弧长方差大；虚点使弧更碎。哈希仍建议通用或密码学视对抗模型。故障：节点消失，弧并到后继，与「加节点」对偶。</p><p>后课近似结构假定流或多重集，不再假设能存全体键。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Dynamo 论文当词条抄。不保证全局最优平衡（那是负载均衡另一层）。草图从 Count-Min 开始允许误差。</p><p>后课默认：集群成员变化用一致性哈希减迁移。流上近似频次用 Count-Min。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一致性哈希：环上后继，增删只动邻近键。</li><li>虚拟节点改善平衡。</li><li>下一课用草图近似计数，不存键。</li><li>出处：Karger et al., <em>STOC</em>, 1997。</li></ul>',9))])}const A=o(c,[["render",m]]);export{E as __pageData,A as default};
